content.text:
                state[cur] = 1
                stack.append(cur)
                cur = tails[e]
            if not ok:
                return False
            acc = base
            while stack:
                nd = stack.pop()
                acc += wts[pa[nd]]
                sums[nd] = acc
                state[nd] = 2
            if sums[b] != ra[b]:
                return False
    return True


def check_plan_witness(fab, g, bounds, ages, preds):
    N = fab.N
    P = fab.P
    wcost = fab.wcost
    is_anchor = fab.is_anchor
    step_info = fab.step_info
    for p in range(P):
        base = p * N
        prev_base = (p - 1) % P * N
        for i in range(N):
            v = base + i
            bv = bounds[v]
            if bv is None:
                if ages[v] is not None or preds[v] is not None:
                    return False
                continue
            av = ages[v]
            if not is_int(bv) or not is_int(av) or bv < 0 or av < 0:
                return False
            pr = preds[v]
            if is_anchor[v]:
                if pr is not None or bv != 0 or av != 0:
                    return False
                continue
            if not isinstance(pr, list) or len(pr) != 2:
                return False
            pv = pr[0]
            kind = pr[1]
            if not is_int(pv) or not is_int(kind):
                return False
            if pv < 0 or pv >= fab.V:
                return False
            bp = bounds[pv]
            ap = ages[pv]
            if bp is None or ap is None:
                return False
            if kind == -1:
                if pv != prev_base + i:
                    return False
                if bv != bp + wcost[pv] or av != ap + 1:
                    return False
            else:
                si = step_info(kind, pv // N, g)
                if si is None:
                    return False
                dv, cost, adel, src = si
                if dv != v or pv % N != src:
                    return False
                if bv != bp + cost or av != ap + adel:
                    return False
    return True


def _audit(profile, fabric, proposal):
    if not isinstance(proposal, dict):
        return False
    n = int(fabric['n'])
    Q = len(fabric['slices'])
    P = utils.declared_period(int(fabric['interval_ns']), int(fabric['slice_ns']), Q)
    guards = fabric['guards_ns']
    cal = para.build_calib(profile)
    if not cal.feasible:
        if set(proposal.keys()) != {"status", "cycle"}:
            return False
        if proposal['status'] != 'inconsistent':
            return False
        cyc = proposal['cycle']
        if not isinstance(cyc, list) or len(cyc) > cal.K:
            return False
        return para.cycle_weight_ok(cyc, cal.tails, cal.heads, cal.weights)
    if set(proposal.keys()) != PLAN_KEYS:
        return False
    if proposal['status'] != 'ok':
        return False
    if not is_int(proposal['period_rounds']) or proposal['period_rounds'] != P:
        return False
    pk = proposal['peaks_as']
    if not isinstance(pk, list) or len(pk) != len(guards):
        return False
    for x in pk:
        if x is not None and not is_int(x):
            return False
    gn = proposal['guard_ns']
    if gn is not None and not is_int(gn):
        return False
    bm = proposal['bounds_as']
    am = proposal['age_rounds']
    pmx = proposal['pred']
    wc = proposal['warmup_cycle']
    if gn is None:
        if bm is not None or am is not None or pmx is not None or wc is not None:
            return False
    else:
        if wc is not None and not is_int(wc):
            return False
        if bm is not None and _flatten(bm, P, n) is None:
            return False
        if am is not None and _flatten(am, P, n) is None:
            return False
        if pmx is not None:
            if not isinstance(pmx, list) or len(pmx) != P:
                return False
            for row in pmx:
                if not isinstance(row, list) or len(row) != n:
                    return False
    if not check_calib_cert(cal, proposal['profile']):
        return False
    fab = topo.Fabric(fabric, cal)
    peaks, sel, res = evaluate_guards(fab)
    if len(peaks) != len(pk):
        return False
    for a, b in zip(peaks, pk):
        if a != b or (a is None) != (b is None):
            return False
    if sel != gn:
        return False
    if sel is None:
        return True
    brows, arows, prows, warm = matrices(fab, res)
    if wc != warm:
        return False
    fb = _flatten(bm, P, n)
    fa = _flatten(am, P, n)
    if fb is None or fa is None:
        return False
    tfb = [x for row in brows for x in row]
    tfa = [x for row in arows for x in row]
    if fb != tfb or fa != tfa:
        return False
    fp = []
    for row in pmx:
        fp.extend(row)
    if not check_plan_witness(fab, sel, fb, fa, fp):
        return False
    return True


def audit(profile, fabric, proposal):
    try:
        return {"valid": bool(_audit(profile, fabric, proposal))}
    except Exception:
        return {"valid": False}
